head.script:
scwin.onpageload = function() {
    var data = ["1", "1", "2", "2", "3", "3"];
    dataList1.setData(data);
    dataList2.setData(data);
    dataList3.setData(data);
};
scwin.onpageunload = function() {};
scwin.fireMouseHover = function(node) {
    if (document.createEventObject) {
        node.fireEvent('onmouseover');
    } else if (document.createEvent) {
        var evt = document.createEvent('MouseEvents');
        evt.initEvent('mouseover', true, false);
        node.dispatchEvent(evt);
    } else if (typeof node.onmouseover == 'function') {
        node.onmouseover();
    }
}
scwin.__triggerMouseover = function(id) {
    var el = WebSquare.wUnit.getDomById($p.id + id);
    scwin.fireMouseHover(el);
}
scwin.__hasClass = function() {
    var el0 = WebSquare.wUnit.getJq("#selectbox1");
    return WebSquare.wUnit.getJq(el0).hasClass("w2selectbox_body_over");
}
scwin.unitTest = function() {
    //Unit
    WebSquare.wUnit.start();
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "scwin.__triggerMouseover('selectbox1')");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "scwin.__hasClass()", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run test and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
